def fm(t): return yaml.safe_load(re.match(r'\\A---\\n(.*?)\\n---\\n',t,re.S).group(1))
def items(t):
 out={}
 for b in re.findall(r'"'```yaml items'"\\n(.*?)\\n"'```'"',t,re.S):
  d=yaml.safe_load(b); assert len(d)==1; out.update(d)
 return out
a=fm(text); old=fm(before); prdtext=Path('docs/specs/prd/PRD-001.md').read_text(); prd=fm(prdtext); reqs=items(prdtext); blocks=items(text)
row='| 1 | 2026-09-28 | codex (session unknown) | Reviewed against PRD-001 v2: reuse confirmed, no architectural change. Policy resolution: interview.max_calls=8 (default); architecture.mandated_platforms=none (default); quality.required_categories=floor only (default) | none |\\n'
assert text==before.replace('  - {id: PRD-001, relation: informed_by, version: 1, hash: null}', '  - {id: PRD-001, relation: informed_by, version: 2, hash: null}',1).replace('outcome: create\\n','outcome: reuse\\n',1)+row
assert list(a)==['id','type','title','status','version','created','updated','owner','authors','generated_by','reviewed_by','approved_by','approved_on','upstream','supersedes','superseded_by','blocked_by','system','outcome','inspection_scope']
assert a['id']==p.stem and a['type']=='arch' and a['outcome']=='reuse'
assert a['status']==old['status']=='approved' and a['version']==old['version']==1
assert a['upstream']==[dict(id='PRD-001',relation='informed_by',version=prd['version'],hash=None)]
assert blocks==items(before) and set(blocks)=={'components','decisions','evidence'}
assert blocks['components'] and blocks['evidence']
allreq={r['id']:r for key in ['functional_requirements','non_functional_requirements'] for r in reqs[key] if r['status']=='active'}
fields={'components':['id','status','name','responsibility','owns_data','interacts_with','deployment'], 'decisions':['id','status','question','blocking','state','resolved_by','notes','upstream'], 'evidence':['id','status','source','kind','finding','classification']}
for key,prefix in [('components','CMP'),('decisions','DEC'),('evidence','EVD')]:
 for i,x in enumerate(blocks[key],1):
  assert x['id']==f'{prefix}-{i:02}' and x['status'] in ['active','deprecated']
  assert list(x)==fields[key]+(['upstream'] if key=='components' and 'upstream' in x else [])
  for link in x.get('upstream',[]):
   assert link['hash'] is None
   if link['id']=='PRD-001': assert link['item'] in allreq
for d in blocks['decisions']:
 assert d['upstream'] and d['state'] in ['open','resolved']
 assert bool(d['resolved_by'])==(d['state']=='resolved')
 for rid in d['resolved_by']:
  resolver=fm(Path(f'docs/specs/adr/{rid}.md').read_text())
  assert resolver['status']=='accepted' and resolver['superseded_by'] is None
assert any(e['source']=='PRD-001' and e['kind']=='prd' and e['classification']=='context' for e in blocks['evidence'])
assert '[NEEDS ADR: identity provider' in prdtext and blocks['decisions'][0]['upstream'][0]['item']=='FR-001'
assert re.findall(r'"'^## .+$'"',text,re.M)==['## 1. Context and scope','## 2. Quality drivers','## 3. Components','## 4. Architectural questions','## 5. Evidence inspected','## 6. Deployment','## 7. Requirement changes proposed to the PRD owner','## 8. Open questions','## Change Log']
assert not any(s in text for s in ['<"'!--'"','ARCH-000','PRD-000','YYYY-MM-DD'])
assert '"'```mermaid'"\\nflowchart' in text
hashes=json.loads(Path('/tmp/arch001-reuse-hashes.json').read_text())
for f,h in hashes.items():
 if f"'!=str(p): assert hashlib.sha256(Path(f).read_bytes()).hexdigest()==h,f
assert set(hashes)=={str(f) for d in ['"'prd','adr','arch','policy'] for f in Path(f'docs/specs/{d}').glob('*.md')}
print('PASS: exact three-change review record; all other bytes preserved.')
print('PASS: structural checks and ARCH self-check review with historical provenance preserved under review-record exception.')
print('PASS: PRD and ADR unchanged; no new planning documents.')
ready=[]; blocked={}
for rid in allreq:
 ds=[d['id'] for d in blocks['decisions'] if d['status']=='active' and d['blocking'] and any(l.get('item')==rid for l in d['upstream']) and d['state']"'!='"'resolved']
 if ds: blocked[rid]=ds
 else: ready.append(rid)
print('Ready:', ', '.join(ready)); print('Blocked:',json.dumps(blocked))
print('NOT_RUN: application tests (documentation-only review).')
PY"

